def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Create a set of all classes and their bases
    all_classes = set(classes)
    for cls in classes:
        all_classes.update(cls.__bases__)

    # Create a dictionary to store the direct bases of each class
    base_dict = {cls: set(cls.__bases__) for cls in all_classes}

    # Function to find the minimal bases
    def find_minimal_bases(cls, visited):
        if cls in visited:
            return set()
        visited.add(cls)
        minimal_bases = set()
        for base in base_dict[cls]:
            minimal_bases.update(find_minimal_bases(base, visited))
        minimal_bases.discard(cls)
        return minimal_bases

    # Find the minimal bases for each class
    minimal_bases_set = set()
    for cls in classes:
        minimal_bases_set.update(find_minimal_bases(cls, set()))

    # Return the minimal bases in the order they appear in the input list
    return [cls for cls in classes if cls not in minimal_bases_set]
