def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        spec_version = inventory.get('type')
        if spec_version and spec_version in self.supported_versions:
            self.spec_version = spec_version
        else:
            raise ValueError("Invalid or missing type value in inventory")

    for item in inventory:
        self._validate_item(item)

    return True

def _validate_item(self, item):
    """Validate a single item against the current specification version."""
    spec = self.specifications.get(self.spec_version)
    if not spec:
        raise ValueError(f"No specification found for version {self.spec_version}")

    for field, field_spec in spec.items():
        if field not in item:
            if field_spec.get('required', False):
                raise ValueError(f"Missing required field '{field}' in item")
            continue

        value = item[field]
        field_type = field_spec['type']

        if isinstance(field_type, Schema):
            field_type.validate(value)
        elif isinstance(field_type, Array):
            if not all(isinstance(v, field_type.contained_type) for v in value):
                raise ValueError(f"Invalid type for field '{field}' in item")
        elif not isinstance(value, field_type):
            raise ValueError(f"Invalid type for field '{field}' in item")

    return True
